#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <optional>
#include <string>
#include <vector>

namespace
{
    std::uint16_t be16(const std::vector<std::uint8_t>& b, std::size_t i)
    {
        return static_cast<std::uint16_t>((b[i] << 8) | b[i + 1]);
    }

    std::uint32_t be32(const std::vector<std::uint8_t>& b, std::size_t i)
    {
        return (std::uint32_t{ be16(b, i) } << 16) | be16(b, i + 2);
    }

    std::uint32_t read32(const std::vector<std::uint8_t>& b, std::size_t i, bool big)
    {
        if (big) return be32(b, i);
        return (std::uint32_t{ b[i + 3] } << 24) | (std::uint32_t{ b[i + 2] } << 16) | (std::uint32_t{ b[i + 1] } << 8) | b[i];
    }

    std::string dotted(std::uint32_t ip)
    {
        return std::to_string(ip >> 24) + '.' + std::to_string((ip >> 16) & 0xFF) + '.'
             + std::to_string((ip >> 8) & 0xFF) + '.' + std::to_string(ip & 0xFF);
    }

    bool checksumOk(const std::vector<std::uint8_t>& b, std::size_t begin, std::size_t length)
    {
        std::uint32_t sum{ 0 };
        for (std::size_t i{ 0 }; i < length; i += 2)
        {
            sum += (std::uint32_t{ b[begin + i] } << 8) | (i + 1 < length ? b[begin + i + 1] : 0u);
            sum = (sum & 0xFFFF) + (sum >> 16);
        }
        return sum == 0xFFFF;
    }

    std::string tcpFlags(std::uint8_t f)
    {
        std::string s;
        if (f & 0x02) s += 'S';
        if (f & 0x01) s += 'F';
        if (f & 0x04) s += 'R';
        if (f & 0x08) s += 'P';
        if (f & 0x20) s += 'U';
        if (f & 0x10) s += '.';
        return s.empty() ? "none" : s;
    }

    std::optional<std::string> dnsSummary(const std::vector<std::uint8_t>& b, std::size_t begin, std::size_t end)
    {
        if (end < begin || end - begin < 12) return std::nullopt;
        const std::uint16_t flags{ be16(b, begin + 2) };
        const std::uint16_t questions{ be16(b, begin + 4) };
        const std::uint16_t answers{ be16(b, begin + 6) };
        if (questions == 0) return std::nullopt;
        std::size_t at{ begin + 12 };
        std::string name;
        for (;;)
        {
            if (at >= end) return std::nullopt;
            const std::uint8_t length{ b[at++] };
            if (length == 0) break;
            if (length & 0xC0) return std::nullopt;
            if (end - at < length) return std::nullopt;
            if (!name.empty()) name += '.';
            for (std::size_t i{ 0 }; i < length; ++i) name += static_cast<char>(b[at + i]);
            at += length;
        }
        if (end - at < 4) return std::nullopt;
        if (name.empty()) name = ".";
        if ((flags & 0x8000) == 0) return "DNS query " + name;
        if ((flags & 0x000F) == 3) return "DNS response " + name + ", no such name";
        return "DNS response " + name + ", " + std::to_string(answers) + (answers == 1 ? " answer" : " answers");
    }
}

std::string dissect(const std::vector<std::uint8_t>& f)
{
    if (f.size() < 14) return "[truncated]";
    std::uint16_t type{ be16(f, 12) };
    std::size_t at{ 14 };
    if (type == 0x8100)
    {
        if (f.size() < 18) return "[truncated]";
        type = be16(f, 16);
        at = 18;
    }
    if (type == 0x0806) return "ARP";
    if (type == 0x86DD)
    {
        if (f.size() - at < 40) return "[truncated]";
        return "IP6 next header " + std::to_string(f[at + 6]) + ", length " + std::to_string(be16(f, at + 4));
    }
    if (type != 0x0800)
    {
        char hex[8];
        std::snprintf(hex, sizeof hex, "%04x", static_cast<unsigned>(type));
        return "ethertype 0x" + std::string(hex) + ", length " + std::to_string(f.size());
    }

    const std::size_t available{ f.size() - at };
    if (available < 20) return "[truncated]";
    const std::size_t headerLength{ (f[at] & 0x0Fu) * 4u };
    const std::size_t totalLength{ be16(f, at + 2) };
    if ((f[at] >> 4) != 4 || headerLength < 20 || totalLength < headerLength) return "[malformed]";
    if (headerLength > available) return "[truncated]";

    const std::size_t ipEnd{ at + std::min(totalLength, available) };
    const std::size_t dataLength{ totalLength - headerLength };
    const std::string source{ dotted(be32(f, at + 12)) };
    const std::string destination{ dotted(be32(f, at + 16)) };
    const std::string bad{ checksumOk(f, at, headerLength) ? "" : " [bad checksum]" };
    const std::uint16_t fragmentOffset{ static_cast<std::uint16_t>(be16(f, at + 6) & 0x1FFF) };
    const std::uint8_t protocol{ f[at + 9] };
    const std::string plain{ "IP " + source + " > " + destination + ": " };
    const std::size_t t{ at + headerLength };
    const std::size_t captured{ ipEnd - t };

    if (fragmentOffset != 0)
        return plain + "fragment offset " + std::to_string(fragmentOffset * 8) + ", length " + std::to_string(dataLength) + bad;

    if (protocol == 6)
    {
        if (captured < 20) return plain + "[truncated]" + bad;
        const std::size_t tcpLength{ (f[t + 12] >> 4) * 4u };
        if (tcpLength < 20 || tcpLength > dataLength) return plain + "[malformed]" + bad;
        if (tcpLength > captured) return plain + "[truncated]" + bad;
        const std::uint8_t flags{ f[t + 13] };
        std::string line{ "IP " + source + "." + std::to_string(be16(f, t)) + " > " + destination + "."
                          + std::to_string(be16(f, t + 2)) + ": Flags [" + tcpFlags(flags) + "], seq "
                          + std::to_string(be32(f, t + 4)) };
        if (flags & 0x10) line += ", ack " + std::to_string(be32(f, t + 8));
        line += ", win " + std::to_string(be16(f, t + 14)) + ", length " + std::to_string(dataLength - tcpLength);
        return line + bad;
    }

    if (protocol == 17)
    {
        if (captured < 8) return plain + "[truncated]" + bad;
        const std::uint16_t sourcePort{ be16(f, t) };
        const std::uint16_t destinationPort{ be16(f, t + 2) };
        const std::size_t udpLength{ be16(f, t + 4) };
        const std::string prefix{ "IP " + source + "." + std::to_string(sourcePort) + " > " + destination + "."
                                  + std::to_string(destinationPort) + ": " };
        if (udpLength < 8 || udpLength > dataLength) return prefix + "[malformed]" + bad;
        if (sourcePort == 53 || destinationPort == 53)
        {
            if (const auto dns{ dnsSummary(f, t + 8, std::min(ipEnd, t + udpLength)) })
                return prefix + *dns + bad;
        }
        return prefix + "UDP, length " + std::to_string(udpLength - 8) + bad;
    }

    if (protocol == 1) return plain + "ICMP, length " + std::to_string(dataLength) + bad;
    return plain + "proto " + std::to_string(protocol) + ", length " + std::to_string(dataLength) + bad;
}

std::vector<std::string> dissectFile(const std::vector<std::uint8_t>& file)
{
    std::vector<std::string> lines;
    if (file.size() < 24) return lines;
    bool big{ false };
    bool nano{ false };
    switch (read32(file, 0, false))
    {
    case 0xA1B2C3D4: break;
    case 0xA1B23C4D: nano = true; break;
    case 0xD4C3B2A1: big = true; break;
    case 0x4D3CB2A1: big = true; nano = true; break;
    default: return lines;
    }
    const std::uint16_t major{ static_cast<std::uint16_t>(big ? be16(file, 4) : (file[5] << 8) | file[4]) };
    if (major != 2 || read32(file, 20, big) != 1) return lines;

    std::size_t at{ 24 };
    bool first{ true };
    std::int64_t start{ 0 };
    while (file.size() - at >= 16)
    {
        const std::uint32_t seconds{ read32(file, at, big) };
        const std::uint32_t fraction{ read32(file, at + 4, big) };
        const std::uint32_t captured{ read32(file, at + 8, big) };
        if (file.size() - at - 16 < captured) break;
        const std::int64_t micros{ std::int64_t{ seconds } * 1000000 + (nano ? fraction / 1000 : fraction) };
        if (first) { start = micros; first = false; }
        const std::int64_t since{ std::max<std::int64_t>(0, micros - start) };
        char stamp[32];
        std::snprintf(stamp, sizeof stamp, "%lld.%06lld ", static_cast<long long>(since / 1000000),
                      static_cast<long long>(since % 1000000));
        const auto begin{ file.begin() + static_cast<std::ptrdiff_t>(at + 16) };
        lines.push_back(stamp + dissect(std::vector<std::uint8_t>(begin, begin + static_cast<std::ptrdiff_t>(captured))));
        at += 16 + std::size_t{ captured };
    }
    return lines;
}

