using Bytes = std::vector<std::uint8_t>;
void put16(Bytes& b, std::size_t v) { b.push_back(static_cast<std::uint8_t>(v >> 8)); b.push_back(static_cast<std::uint8_t>(v)); }
void put32(Bytes& b, std::uint32_t v) { put16(b, v >> 16); put16(b, v & 0xFFFF); }
std::uint16_t headerSum(const Bytes& b) {
    std::uint32_t sum{ 0 };
    for (std::size_t i{ 0 }; i + 1 < b.size(); i += 2) { sum += (std::uint32_t{ b[i] } << 8) | b[i + 1]; sum = (sum & 0xFFFF) + (sum >> 16); }
    return static_cast<std::uint16_t>(~sum & 0xFFFF);
}
Bytes frame(std::uint16_t type, const Bytes& payload) {
    Bytes f{ 0x3C, 0x22, 0xFB, 0x12, 0x9A, 0x01, 0x00, 0x11, 0x22, 0x33, 0x44, 0x55 };
    put16(f, type);
    f.insert(f.end(), payload.begin(), payload.end());
    return f;
}
const std::uint32_t ME{ 0x0A000002 }, ROUTER{ 0x0A000001 }, WEB{ 0x5DB8D822 };
Bytes ipv4(std::uint8_t protocol, std::uint32_t source, std::uint32_t destination, const Bytes& payload, std::uint16_t fragment = 0x4000) {
    Bytes h{ 0x45, 0x00 };
    put16(h, 20 + payload.size()); put16(h, 0x1234); put16(h, fragment);
    h.push_back(64); h.push_back(protocol); put16(h, 0);
    put32(h, source); put32(h, destination);
    const std::uint16_t c{ headerSum(h) };
    h[10] = static_cast<std::uint8_t>(c >> 8); h[11] = static_cast<std::uint8_t>(c);
    h.insert(h.end(), payload.begin(), payload.end());
    return h;
}
Bytes tcp(std::uint16_t sp, std::uint16_t dp, std::uint32_t seq, std::uint32_t ack, std::uint8_t flags, std::uint16_t window, const std::string& data) {
    Bytes s;
    put16(s, sp); put16(s, dp); put32(s, seq); put32(s, ack);
    s.push_back(0x50); s.push_back(flags); put16(s, window); put16(s, 0); put16(s, 0);
    s.insert(s.end(), data.begin(), data.end());
    return s;
}
Bytes udp(std::uint16_t sp, std::uint16_t dp, const Bytes& data) {
    Bytes s;
    put16(s, sp); put16(s, dp); put16(s, 8 + data.size()); put16(s, 0);
    s.insert(s.end(), data.begin(), data.end());
    return s;
}
Bytes dnsMessage(std::uint16_t flags, std::uint16_t answers, const std::string& name) {
    Bytes m;
    put16(m, 0x1234); put16(m, flags); put16(m, 1); put16(m, answers); put16(m, 0); put16(m, 0);
    std::size_t start{ 0 };
    while (start < name.size()) {
        std::size_t dot{ name.find('.', start) };
        if (dot == std::string::npos) dot = name.size();
        m.push_back(static_cast<std::uint8_t>(dot - start));
        m.insert(m.end(), name.begin() + static_cast<std::ptrdiff_t>(start), name.begin() + static_cast<std::ptrdiff_t>(dot));
        start = dot + 1;
    }
    m.push_back(0);
    put16(m, 1); put16(m, 1);
    return m;
}
