             std::string("IP 10.0.0.2.50000 > 93.184.216.34.80: Flags [S], seq 100, win 64240, length 0"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(6, WEB, ME, tcp(80, 50000, 5000, 101, 0x12, 65160, "")))),
             std::string("IP 93.184.216.34.80 > 10.0.0.2.50000: Flags [S.], seq 5000, ack 101, win 65160, length 0"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(6, ME, WEB, tcp(50000, 80, 101, 5001, 0x18, 512, "hello")))),
             std::string("IP 10.0.0.2.50000 > 93.184.216.34.80: Flags [P.], seq 101, ack 5001, win 512, length 5"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(6, ME, WEB, tcp(50000, 80, 106, 5001, 0x11, 512, "")))),
             std::string("IP 10.0.0.2.50000 > 93.184.216.34.80: Flags [F.], seq 106, ack 5001, win 512, length 0"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(6, WEB, ME, tcp(80, 50001, 0, 0, 0x04, 0, "")))),
             std::string("IP 93.184.216.34.80 > 10.0.0.2.50001: Flags [R], seq 0, win 0, length 0"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(6, ME, WEB, tcp(1, 2, 3, 4, 0, 5, "")))),
             std::string("IP 10.0.0.2.1 > 93.184.216.34.2: Flags [none], seq 3, win 5, length 0"));
    Bytes padded{ frame(0x0800, ipv4(6, ME, WEB, tcp(50000, 80, 101, 5001, 0x10, 512, ""))) };
    padded.resize(60, 0);
    CHECK_EQ(dissect(padded), std::string("IP 10.0.0.2.50000 > 93.184.216.34.80: Flags [.], seq 101, ack 5001, win 512, length 0"));
}
TEST("UDP and DNS lines") {
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, udp(5000, 6000, { 1, 2, 3 })))),
             std::string("IP 10.0.0.2.5000 > 10.0.0.1.6000: UDP, length 3"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, udp(53000, 53, dnsMessage(0x0100, 0, "xenon.justloofy.dev"))))),
             std::string("IP 10.0.0.2.53000 > 10.0.0.1.53: DNS query xenon.justloofy.dev"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ROUTER, ME, udp(53, 53000, dnsMessage(0x8180, 2, "xenon.justloofy.dev"))))),
             std::string("IP 10.0.0.1.53 > 10.0.0.2.53000: DNS response xenon.justloofy.dev, 2 answers"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ROUTER, ME, udp(53, 53000, dnsMessage(0x8180, 1, "example.com"))))),
             std::string("IP 10.0.0.1.53 > 10.0.0.2.53000: DNS response example.com, 1 answer"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ROUTER, ME, udp(53, 53000, dnsMessage(0x8183, 0, "nope.example"))))),
             std::string("IP 10.0.0.1.53 > 10.0.0.2.53000: DNS response nope.example, no such name"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, udp(53000, 53, dnsMessage(0x0100, 0, ""))))),
             std::string("IP 10.0.0.2.53000 > 10.0.0.1.53: DNS query ."));
    Bytes brokenDns{ dnsMessage(0x0100, 0, "xenon.justloofy.dev") };
    brokenDns[12] = 60;
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, udp(53000, 53, brokenDns)))),
             std::string("IP 10.0.0.2.53000 > 10.0.0.1.53: UDP, length ") + std::to_string(brokenDns.size()));
    Bytes pointer{ dnsMessage(0x0100, 0, "a.b") };
    pointer[12] = 0xC0;
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, udp(53000, 53, pointer)))),
             std::string("IP 10.0.0.2.53000 > 10.0.0.1.53: UDP, length ") + std::to_string(pointer.size()));
    Bytes udpTooLong{ udp(1, 2, { 9, 9 }) };
    udpTooLong[5] = 50;
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, udpTooLong))), std::string("IP 10.0.0.2.1 > 10.0.0.1.2: [malformed]"));
}
