    bad[14 + 8] = 1;
    CHECK_EQ(dissect(bad), std::string("IP 10.0.0.2 > 10.0.0.1: ICMP, length 8 [bad checksum]"));
    Bytes tagged{ 0x00, 0x05, 0x08, 0x00 };
