    Bytes v6(40, 0); v6[0] = 0x60; v6[5] = 20; v6[6] = 6;
    CHECK_EQ(dissect(frame(0x86DD, v6)), std::string("IP6 next header 6, length 20"));
    CHECK_EQ(dissect(frame(0x86DD, Bytes(39, 0))), std::string("[truncated]"));
