TEST("truncated and malformed packets") {
    CHECK_EQ(dissect(Bytes(13, 0)), std::string("[truncated]"));
    CHECK_EQ(dissect(frame(0x8100, { 0, 5, 8 })), std::string("[truncated]"));
    Bytes full{ frame(0x0800, ipv4(6, ME, WEB, tcp(50000, 80, 101, 5001, 0x18, 512, std::string(100, 'x')))) };
    Bytes headersOnly{ full.begin(), full.begin() + 54 };
    CHECK_EQ(dissect(headersOnly), std::string("IP 10.0.0.2.50000 > 93.184.216.34.80: Flags [P.], seq 101, ack 5001, win 512, length 100"));
    Bytes halfTcp{ full.begin(), full.begin() + 44 };
    CHECK_EQ(dissect(halfTcp), std::string("IP 10.0.0.2 > 93.184.216.34: [truncated]"));
    Bytes halfIp{ full.begin(), full.begin() + 33 };
    CHECK_EQ(dissect(halfIp), std::string("[truncated]"));
    Bytes version{ full }; version[14] = 0x65;
    CHECK_EQ(dissect(version), std::string("[malformed]"));
    Bytes total{ full }; total[16] = 0; total[17] = 10;
    CHECK_EQ(dissect(total), std::string("[malformed]"));
    Bytes options{ full }; options[14] = 0x4F;
    CHECK_EQ(dissect(Bytes(options.begin(), options.begin() + 60)), std::string("[truncated]"));
    Bytes tcpOffset{ full }; tcpOffset[46] = 0x40;
    CHECK_EQ(dissect(tcpOffset), std::string("IP 10.0.0.2 > 93.184.216.34: [malformed]"));
    Bytes tcpOptions{ full }; tcpOptions[46] = 0xF0;
    CHECK_EQ(dissect(Bytes(tcpOptions.begin(), tcpOptions.begin() + 70)), std::string("IP 10.0.0.2 > 93.184.216.34: [truncated]"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, Bytes(4, 0)))), std::string("IP 10.0.0.2 > 10.0.0.1: [truncated]"));
}
void le32(Bytes& b, std::uint32_t v) { for (int i{ 0 }; i < 4; ++i) b.push_back(static_cast<std::uint8_t>(v >> (8 * i))); }
Bytes pcap(bool big, std::uint32_t magic, std::uint32_t link) {
    Bytes f;
    if (big) { put32(f, magic); put16(f, 2); put16(f, 4); put32(f, 0); put32(f, 0); put32(f, 65535); put32(f, link); }
    else { le32(f, magic); f.insert(f.end(), { 2, 0, 4, 0 }); le32(f, 0); le32(f, 0); le32(f, 65535); le32(f, link); }
    return f;
}
void record(Bytes& f, bool big, std::uint32_t sec, std::uint32_t frac, const Bytes& data) {
    const auto n{ static_cast<std::uint32_t>(data.size()) };
    if (big) { put32(f, sec); put32(f, frac); put32(f, n); put32(f, n); }
    else { le32(f, sec); le32(f, frac); le32(f, n); le32(f, n); }
    f.insert(f.end(), data.begin(), data.end());
}
TEST("whole capture files") {
    const Bytes syn{ frame(0x0800, ipv4(6, ME, WEB, tcp(50000, 80, 100, 0, 0x02, 64240, ""))) };
    const Bytes arp{ frame(0x0806, Bytes(28, 0)) };
    Bytes le{ pcap(false, 0xA1B2C3D4, 1) };
    record(le, false, 1700000000, 250000, syn);
    record(le, false, 1700000001, 100, arp);
    record(le, false, 1699999999, 0, arp);
    const auto lines{ dissectFile(le) };
    CHECK_EQ(lines.size(), 3u);
    if (lines.size() == 3) {
        CHECK_EQ(lines[0], std::string("0.000000 IP 10.0.0.2.50000 > 93.184.216.34.80: Flags [S], seq 100, win 64240, length 0"));
        CHECK_EQ(lines[1], std::string("0.750100 ARP"));
        CHECK_EQ(lines[2], std::string("0.000000 ARP"));
    }
    Bytes be{ pcap(true, 0xA1B23C4D, 1) };
    record(be, true, 10, 0, arp);
    record(be, true, 12, 500000000, arp);
    record(be, true, 13, 0, arp);
    be.resize(be.size() - 3);
    const auto nano{ dissectFile(be) };
    CHECK_EQ(nano.size(), 2u);
    if (nano.size() == 2) CHECK_EQ(nano[1], std::string("2.500000 ARP"));
    Bytes wifi{ pcap(false, 0xA1B2C3D4, 105) };
    record(wifi, false, 1, 0, arp);
    CHECK(dissectFile(wifi).empty());
    CHECK(dissectFile(Bytes(24, 0)).empty());
