TEST("UDP and DNS lines") {
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, udp(5000, 6000, { 1, 2, 3 })))),
             std::string("IP 10.0.0.2.5000 > 10.0.0.1.6000: UDP, length 3"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, udp(53000, 53, dnsMessage(0x0100, 0, "xenon.justloofy.dev"))))),
             std::string("IP 10.0.0.2.53000 > 10.0.0.1.53: DNS query xenon.justloofy.dev"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ROUTER, ME, udp(53, 53000, dnsMessage(0x8180, 2, "xenon.justloofy.dev"))))),
             std::string("IP 10.0.0.1.53 > 10.0.0.2.53000: DNS response xenon.justloofy.dev, 2 answers"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ROUTER, ME, udp(53, 53000, dnsMessage(0x8180, 1, "example.com"))))),
             std::string("IP 10.0.0.1.53 > 10.0.0.2.53000: DNS response example.com, 1 answer"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ROUTER, ME, udp(53, 53000, dnsMessage(0x8183, 0, "nope.example"))))),
             std::string("IP 10.0.0.1.53 > 10.0.0.2.53000: DNS response nope.example, no such name"));
    CHECK_EQ(dissect(frame(0x0800, ipv4(17, ME, ROUTER, udp(53000, 53, dnsMessage(0x0100, 0, ""))))),
             std::string("IP 10.0.0.2.53000 > 10.0.0.1.53: DNS query ."));
    Bytes brokenDns{ dnsMessage(0x0100, 0, "xenon.justloofy.dev") };
    brokenDns[12] = 60;
